    setSel(s => ({ ...s, tareas: [...(s.tareas || []), tarea] }));
    setNuevaTareaForm({ titulo: '', descripcion: '', responsable_id: '', tecnico_id: '', fecha_limite: '', horas_estimadas: '', orden: tareasOT.length });
